-- Suppression de l'ancienne table pour mettre à jour la structure des colonnes
DROP TABLE IF EXISTS predictibilites_ia_choix_medecin;

-- Création de la nouvelle table
CREATE TABLE predictibilites_ia_choix_medecin (
    trigramme VARCHAR(10) PRIMARY KEY,
    repartition_colonnes TEXT,
    score_predictibilite DECIMAL(8,4),
    repos_moyen_heures DECIMAL(8,2),
    nb_entrees_non_nulles INTEGER
);

